    exponent = inputs['exponent']
    modulus = inputs['modulus']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices mod modulus"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(M, exp, mod):
        """Compute M^exp mod modulus using binary exponentiation"""
        if exp == 0:
            return [[1, 0], [0, 1]]  # Identity matrix

        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in M]  # Copy M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result = matrix_power(matrix, exponent, modulus)

    # Sum all entries
    total = sum(sum(row) for row in result)
    return float(total)

